action.target:
var product_id = document.querySelector('#DataTables_Table_0 > tbody > tr > td.text-center.vertical-align-middle.sorting_1').textContent.replaceAll("\n","").trim()

var url = "https://v2.giaonhan247.com/backend/order/edit/" + product_id;

window.location.assign(url);

// Lấy danh sách tất cả các textbox có class là '.note-editable.panel-body' --> Nếu 2 textbox cùng class --> Lấy textbox thứ 2
const editableDivList = document.querySelectorAll('.note-editable.panel-body');
if (editableDivList.length >= 2) {
    const editableDivB = editableDivList[1];

    // Tạo đối tượng <p> mới và cập nhật nội dung
    const paragraph = editableDivB.ownerDocument.createElement("p");
    paragraph.textContent = apizer_input.ghi_chu;
    editableDivB.appendChild(paragraph);

    // Gọi inputEvent và thực hiện eventchange để xác nhận thay đổi cho textbox
    const inputEvent = new Event('input');
    editableDivB.dispatchEvent(inputEvent);

    const changeEvent = new Event('change');
    editableDivB.dispatchEvent(changeEvent);

    // Lấy danh sách tất cả các nút "Lưu" có class '.btn-saveNote' --> Nếu nhiều nút lưu có cùng class --> Click nút Lưu thứ 2 
    const saveButtons = document.querySelectorAll('.btn-saveNote');
    if (saveButtons.length >= 2) {
        const secondSaveButton = saveButtons[1];
        secondSaveButton.click();
    }
}
